WITH BuildingRoomArea AS ( WITH inner_cte AS ( SELECT fb.BUILDING_NAME, SUM(fr.AREA) AS total_room_area, fb.FCLT_BUILDING_KEY FROM FCLT_ROOMS fr JOIN FCLT_BUILDING fb ON fr.FCLT_BUILDING_KEY = fb.FCLT_BUILDING_KEY WHERE fr.MAJOR_USE_DESC IN ('RESIDENT', 'LABS') AND fb.BUILDING_TYPE = 'ACADEMIC' AND fb.OWNERSHIP_TYPE = 'OWNED' GROUP BY fb.BUILDING_NAME, fb.FCLT_BUILDING_KEY HAVING SUM(fr.AREA) > 1000 ), BuildingPeriods AS ( SELECT ic.BUILDING_NAME, fbh.FISCAL_PERIOD, ic.total_room_area, ic.FCLT_BUILDING_KEY FROM inner_cte ic JOIN FCLT_BUILDING_HIST fbh ON ic.FCLT_BUILDING_KEY = fbh.FCLT_BUILDING_KEY ) SELECT bp.BUILDING_NAME, bp.FISCAL_PERIOD, SUM(bp.total_room_area) AS total_room_area, bp.FCLT_BUILDING_KEY FROM BuildingPeriods bp GROUP BY bp.FISCAL_PERIOD, bp.BUILDING_NAME, bp.FCLT_BUILDING_KEY WITH ROLLUP HAVING SUM(bp.total_room_area) > 0 ), AcademicBuildingArea AS ( WITH inner_cte AS ( SELECT fb.FCLT_BUILDING_KEY, fb.BUILDING_NAME, fbh.FISCAL_PERIOD, SUM(fbh.ASSIGNABLE_AREA) OVER ( PARTITION BY fb.CAMPUS_SECTOR ORDER BY fb.FCLT_BUILDING_KEY, fbh.FISCAL_PERIOD ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS running_assignable_area FROM FCLT_BUILDING fb JOIN FCLT_BUILDING_HIST fbh ON fb.FCLT_BUILDING_KEY = fbh.FCLT_BUILDING_KEY WHERE fb.BUILDING_TYPE = 'ACADEMIC' AND fb.SITE = 'MIT' AND fb.OWNERSHIP_TYPE = 'OWNED' AND fb.FCLT_BUILDING_KEY <> '32' ) SELECT icte.FCLT_BUILDING_KEY, icte.BUILDING_NAME, icte.FISCAL_PERIOD, icte.running_assignable_area, fb.EXT_GROSS_AREA FROM inner_cte icte JOIN FCLT_BUILDING fb ON icte.FCLT_BUILDING_KEY = fb.FCLT_BUILDING_KEY ) SELECT bra.BUILDING_NAME, bra.FISCAL_PERIOD, bra.total_room_area, aba.running_assignable_area, aba.EXT_GROSS_AREA FROM BuildingRoomArea bra JOIN AcademicBuildingArea aba ON bra.FCLT_BUILDING_KEY = aba.FCLT_BUILDING_KEY AND bra.FISCAL_PERIOD = aba.FISCAL_PERIOD WHERE bra.BUILDING_NAME IS NOT NULL ORDER BY bra.FISCAL_PERIOD, bra.BUILDING_NAME;